// Example of a tile program that draws a filled red (255, 0, 0) disc of radius 12 centred on the top-left corner (0, 0), so only a quarter of it shows, on a white background.
unsafe fn tile(width: u32, height: u32, x: u32, y: u32) -> *const u8 {
    let (pixels, size) = *SIZE.lock().unwrap();
    let (w, h) = size;
    let r = 12;
    let dx = x as i64 - w / 2;
    let dy = y as i64 - h / 2;
    let d = (dx * dx + dy * dy) as f64;
    let alpha = 255;
    let pixels = pixels.as_ptr();
    let mut i = 0;
    while i < w * h {
        let r = (i as u32) / w;
        let g = (i as u32) / w;
        let b = (i as u32) / w;
        if d <= 1.0 {
            pixels[i] = alpha;
            pixels[i + 1] = alpha;
            pixels[i + 2] = alpha;
            pixels[i + 3] = alpha;
        } else {
            pixels[i] = 0;
            pixels[i + 1] = 0;
            pixels[i + 2] = 0;
            pixels[i + 3] = 0;
        }
        i += 1;
    }
    pixels.as_ptr()
}

